    private boolean rootIsWildcard;
    private DoubleKeyMap<PredictionContext, PredictionContext, PredictionContext> mergeCache;

    public static PredictionContext merge(PredictionContext a, PredictionContext b, boolean rootIsWildcard, DoubleKeyMap<PredictionContext, PredictionContext, PredictionContext> mergeCache) {
        return new Merger(a, b, rootIsWildcard, mergeCache).execute();
    }

    private Merger(PredictionContext a, PredictionContext b, boolean rootIsWildcard, DoubleKeyMap<PredictionContext, PredictionContext, PredictionContext> mergeCache) {
        this.a = a;
        this.b = b;
        this.rootIsWildcard = rootIsWildcard;
        this.mergeCache = mergeCache;
    }

    private PredictionContext execute() {
        // share same graph if both same
        if ((a == null && b == null) || a == b || (a != null && a.equals(b))) return a;

        if (a instanceof SingletonPredictionContext && b instanceof SingletonPredictionContext) {
            return mergeSingletons((SingletonPredictionContext) a,
                                   (SingletonPredictionContext) b,
                                   rootIsWildcard, mergeCache);
        }

        // At least one of a or b is an array
        // If one is $ and rootIsWildcard, return $ as * wildcard
        if (rootIsWildcard) {
            if (a instanceof EmptyPredictionContext) return a;
            if (b instanceof EmptyPredictionContext) return b;
        }

        // convert singleton so both are arrays to normalize
        if (a instanceof SingletonPredictionContext) {
            a = new ArrayPredictionContext((SingletonPredictionContext) a);
        }
