private boolean handleRuleStopState(CharStream input, LexerATNConfig config, ATNConfigSet configs, boolean currentAltReachedAcceptState) {
    if (debug) {
        logRuleStopState(config);
    }

    if (config.context == null || config.context.hasEmptyPath()) {
        if (isContextEmpty(config.context)) {
            configs.add(config);
            return true;
