private boolean processSingletonPredictionContext(CharStream input, LexerATNConfig config, SingletonPredictionContext ctx, boolean currentAltReachedAcceptState, ATNConfigSet configs) {
    if (!ctx.isEmpty()) {
        PredictionContext newContext = ctx.parent; // "pop" return state
