        return new IntervalSet[s.getNumberOfTransitions() + 1];
    } else {
        LL1Analyzer anal = new LL1Analyzer(g.atn);
        IntervalSet[] look = anal.getDecisionLookahead(s);
        g.tool.log("LL1", "look=" + Arrays.toString(look));
        return look;
    }
}

