public String decode(char[] data) {
    data = data.clone();
    adjustData(data);

    StringBuilder buf = new StringBuilder();
    int p = 0;

    int version = getVersion(data, p);
    validateVersion(version);

    int grammarType = ATNSimulator.toInt(data[p++]);
    int maxType = ATNSimulator.toInt(data[p++]);
    buf.append("max type ").append(maxType).append("\
");

    int nstates = ATNSimulator.toInt(data[p++]);
    processStates(data, buf, p, nstates);

    int numNonGreedyStates = ATNSimulator.toInt(data[p++]);
    skipNonGreedyStates(data, p, numNonGreedyStates);

    int nrules = ATNSimulator.toInt(data[p++]);
    processRules(data, buf, p, nrules);

    int nmodes = ATNSimulator.toInt(data[p++]);
    processModes(data, buf, p, nmodes);

    int nsets = ATNSimulator.toInt(data[p++]);
    processSets(data, buf, p, nsets);

    int nedges = ATNSimulator.toInt(data[p++]);
    processEdges(data, buf, p, nedges);

    int ndecisions = ATNSimulator.toInt(data[p++]);
    processDecisions(data, buf, p, ndecisions);

    return buf.toString();
}

private void adjustData(char[] data) {
    for (int i = 1; i < data.length; i++) {
        data[i] = (char) (data[i] - 2);
    }
}

private int getVersion(char[] data, int p) {
    return ATNSimulator.toInt(data[p++]);
}

private void validateVersion(int version) {
    if (version != ATNSimulator.SERIALIZED_VERSION) {
        String reason = String.format("Could not deserialize ATN with version %d (expected %d).", version, ATNSimulator.SERIALIZED_VERSION);
        throw new UnsupportedOperationException(new InvalidClassException(ATN.class.getName(), reason));
    }
}

private void processStates(char[] data, StringBuilder buf, int p, int nstates) {
    for (int i = 1; i <= nstates; i++) {
        int stype = ATNSimulator.toInt(data[p++]);
        if (stype == ATNState.INVALID_TYPE) continue;

        int ruleIndex = ATNSimulator.toInt(data[p++]);
        String arg = getStateArg(data, stype, p);
        buf.append(i - 1).append(":")
            .append(ATNState.serializationNames.get(stype)).append(" ")
            .append(ruleIndex).append(arg).append("\
");
    }
}

private String getStateArg(char[] data, int stype, int p) {
    String arg = "";
    if (stype == ATNState.LOOP_END) {
        int loopBackStateNumber = ATNSimulator.toInt(data[p++]);
        arg = " " + loopBackStateNumber;
    } else if (isBlockStartType(stype)) {
        int endStateNumber = ATNSimulator.toInt(data[p++]);
        arg = " " + endStateNumber;
    }
    return arg;
}

private boolean isBlockStartType(int stype) {
    return stype == ATNState.PLUS_BLOCK_START || stype == ATNState.STAR_BLOCK_START || stype == ATNState.BLOCK_START;
}

private void skipNonGreedyStates(char[] data, int p, int numNonGreedyStates) {
    for (int i = 0; i < numNonGreedyStates; i++) {
        ATNSimulator.toInt(data[p++]);
    }
}

private void processRules(char[] data, StringBuilder buf, int p, int nrules) {
    for (int i = 0; i < nrules; i++) {
        int s = ATNSimulator.toInt(data[p++]);
        if (g.isLexer()) {
            int arg1 = ATNSimulator.toInt(data[p++]);
            int arg2 = ATNSimulator.toInt(data[p++]);
            buf.append("rule ").append(i).append(":").append(s).append(" ")
                .append(arg1).append(",").append(arg2).append(\'\
\');
        } else {
            buf.append("rule ").append(i).append(":").append(s).append(\'\
\');
        }
    }
}

private void processModes(char[] data, StringBuilder buf, int p, int nmodes) {
    for (int i = 0; i < nmodes; i++) {
        int s = ATNSimulator.toInt(data[p++]);
        buf.append("mode ").append(i).append(":").append(s).append(\'\
\');
    }
}

private void processSets(char[] data, StringBuilder buf, int p, int nsets) {
    for (int i = 1; i <= nsets; i++) {
        int nintervals = ATNSimulator.toInt(data[p++]);
        buf.append(i - 1).append(":");
        for (int j = 1; j <= nintervals; j++) {
            if (j > 1) buf.append(", ");
            buf.append(getTokenNameInterval(data, p));
            p += 2;
        }
        buf.append("\
");
    }
}

private String getTokenNameInterval(char[] data, int p) {
    return getTokenName(ATNSimulator.toInt(data[p])) + ".." + getTokenName(ATNSimulator.toInt(data[p + 1]));
}

private void processEdges(char[] data, StringBuilder buf, int p, int nedges) {
    for (int i = 1; i <= nedges; i++) {
        int src = ATNSimulator.toInt(data[p]);
        int trg = ATNSimulator.toInt(data[p + 1]);
        int ttype = ATNSimulator.toInt(data[p + 2]);
        int arg1 = ATNSimulator.toInt(data[p + 3]);
        int arg2 = ATNSimulator.toInt(data[p + 4]);
        int arg3 = ATNSimulator.toInt(data[p + 5]);
        buf.append(src).append("->").append(trg)
            .append(" ").append(Transition.serializationNames.get(ttype))
            .append(" ").append(arg1).append(",").append(arg2).append(",").append(arg3)
            .append("\
");
        p += 6;
    }
}

private void processDecisions(char[] data, StringBuilder buf, int p, int ndecisions) {
    for (int i = 1; i <= ndecisions; i++) {
        int s = ATNSimulator.toInt(data[p++]);
        buf.append(i - 1).append(":").append(s).append("\
");
    }
}

