public String asString() {
    if (start == null) return null;

    Set<ATNState> marked = new HashSet<>();
    List<ATNState> work = new ArrayList<>();
    work.add(start);

    StringBuilder buf = new StringBuilder();

    while (!work.isEmpty()) {
        ATNState currentState = work.remove(0);
        if (marked.contains(currentState)) continue;

        marked.add(currentState);
        int transitionCount = currentState.getNumberOfTransitions();

        for (int i = 0; i < transitionCount; i++) {
            Transition transition = currentState.transition(i);
            handleTransition(work, buf, currentState, transition);
        }
    }
    return buf.toString();
}

private void handleTransition(List<ATNState> work, StringBuilder buf, ATNState currentState, Transition transition) {
    if (!(currentState instanceof RuleStopState)) {
        if (transition instanceof RuleTransition) {
            work.add(((RuleTransition) transition).followState);
        } else {
            work.add(transition.target);
        }
    }

    buf.append(getStateString(currentState));
    appendTransitionString(buf, transition);
}

private void appendTransitionString(StringBuilder buf, Transition transition) {
    if (transition instanceof EpsilonTransition) {
        buf.append("->").append(getStateString(transition.target)).append(\'\
\');
    } else if (transition instanceof RuleTransition) {
        buf.append("-").append(g.getRule(((RuleTransition) transition).ruleIndex).name)
           .append("->").append(getStateString(transition.target)).append(\'\
\');
    } else if (transition instanceof ActionTransition) {
        buf.append("-").append(transition.toString())
           .append("->").append(getStateString(transition.target)).append(\'\
\');
    } else if (transition instanceof SetTransition) {
        appendSetTransitionString(buf, (SetTransition) transition);
    } else if (transition instanceof AtomTransition) {
        AtomTransition atomTransition = (AtomTransition) transition;
        String label = g.getTokenDisplayName(atomTransition.label);
        buf.append("-").append(label)
           .append("->").append(getStateString(transition.target)).append(\'\
\');
    } else {
        buf.append("-").append(transition.toString())
           .append("->").append(getStateString(transition.target)).append(\'\
\');
    }
}

private void appendSetTransitionString(StringBuilder buf, SetTransition setTransition) {
    boolean isNotSet = setTransition instanceof NotSetTransition;
    if (g.isLexer()) {
        buf.append("-").append(isNotSet ? "~" : "").append(setTransition.toString())
           .append("->").append(getStateString(setTransition.target)).append(\'\
\');
    } else {
        buf.append("-").append(isNotSet ? "~" : "").append(setTransition.label().toString(g.getTokenNames()))
           .append("->").append(getStateString(setTransition.target)).append(\'\
\');
    }
}

